/**
 * @method
 * @name cmb_DEP_CD_2_onselchange
 * @description cmb_DEP_CD_2 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_2_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD_2.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO_2.setValue('');
        }
        dts_EMP_NO_2.UseFilter = true;
        dts_EMP_NO_2.Filter();
        dts_EMP_NO_2.sort("DEP_CD", 0);
        // dts_EMP_NO_2.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF23000.cmb_DEP_CD_2_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_2_OnFilter
 * @description EMP NO 2 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_2_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO_2.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO_2.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF23000.dts_EMP_NO_2_OnFilter" });
    }
};

