/**
 * @method
 * @name setCode
 * @description 2010.03.11 김봉석 대리 요청으로 접수시각을 거래소 제출시각으로, 처리시각을 거래소 접수시각으로 변경
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_DEP_CD_2",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO_2",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_FORM_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_FORM_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions4 = {
        id : "sbm_dts_LIST_BZ_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_LIST_BZ_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_DEP_CD_2.setValue(js_dep_cd);
    // setObjectValue(cmb_EMP_NO_1, js_emp_no) ;

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const cond = scwin.getCondition2();
    // alert ('[cond]'+cond);

    if (chb_main_yn.checked === false && chb_atch_yn.checked === false) {
        await $c.win.alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    url += "&ISUR_CD=" + txb_ISUR_CD_2.getValue();
    url += "&FORM_CD=" + cmb_FORM_CD.getValue();
    url += "&ACPT_SDATE=" + edt_AcptSDate.getValue();
    url += "&ACPT_EDATE=" + edt_AcptEDate.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD_2.getValue();
    url += "&EMP_NO=" + cmb_EMP_NO_2.getValue();
    url += "&DISCLS_PROCS_STAT_CD=" + scwin.getCondition2();
    // url += "&DISCLS_PROCS_STAT_CD=" + getObjectValue(cmb_LIST_PROCS_STAT_CD);
    url += "&UP_DEP_CD=" + js_belngdepcd;
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&MAIN_YN=" + chb_main_yn.getValue();
    url += "&ATTCH_YN=" + chb_atch_yn.getValue();
    // alert("vListMdCd :"+vListMdCd);
    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/ListedReceive.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur2
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD_2.getValue();
    arrPar[1] = txb_COM_NM_2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur2
 * @description set Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur2 = function(arrPar) {
    txb_ISUR_CD_2.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM_2.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name allCheck2
 * @description 2010.03.11 김봉석 대리 요청 접수상태 전체 선택시 모두 체크 되도록
 * @returns {void}
 * @hidden N
 */
scwin.allCheck2 = function() {
    const checkArray = [chb_stat_00, chb_stat_30, chb_stat_40];
    if (chb_stat_99.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_stat_99.checked === false) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

/**
 * @method
 * @name getCondValue
 * @description get Cond Value 처리
 * @param {*} pCnt pCnt
 * @param {*} pVal pVal
 * @param {*} vCode vCode
 * @returns {void}
 * @hidden N
 */
scwin.getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};

/**
 * @method
 * @name getCondition2
 * @description get Condition2 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCondition2 = function() {
    let vStatCnt = 0;
    let vStatCond = '';
    if (chb_stat_99.checked === true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_stat_00.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '00');
            vStatCnt++;
        }
        if (chb_stat_30.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '30');
            vStatCnt++;
        }
        if (chb_stat_40.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, '40');
            vStatCnt++;
        }
    }
    return vStatCond;
};

/**
 * @method
 * @name openDetail
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row, colid) {
    scwin.setContnId(row);
    if (colid === "FORM_KOR_NM") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat, "ULDSTF23000.xml");
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        scwin.gAcptNo = dts_List_2.getCellData(Number(obj), "ACPT_NO");
        scwin.gMainFormCd = dts_List_2.getCellData(Number(obj), "FORM_CD");
        scwin.gFormVer = dts_List_2.getCellData(Number(obj), "FORM_VER");
        scwin.gIsurCd = dts_List_2.getCellData(Number(obj), "ISUR_CD");
    }
};

/**
 * @method
 * @name excelDown
 * @description 엑셀 로그
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDSTF23000.xml", SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List_2, {fileName: "접수처리목록", type: "2"});
};
